//! Multi-byte runs that join the printable ASCII between their characters, held to the decoder
//! before the join (`Parser::set_reference_runs`) and to the per-byte decoder (one byte per
//! read), over generated byte streams cut at random read boundaries and inside sequences:
//! words in several scripts, the ASCII between them, controls and escape sequences, ill-formed
//! bytes (lone continuations, overlongs, surrogates, past U+10FFFF), truncated sequences and
//! runs past the run buffer's capacity.

use super::super::*;
use aterm_provenance::{Provenance, Pty};

/// One sink call, in order; a bulk print is its characters (`Obs`, SPECS.md §0).
#[derive(Debug, Clone, PartialEq, Eq)]
enum Event {
    Print(char),
    Execute(u8),
    Csi(Vec<u16>, Vec<u8>, u8, u32),
    Esc(Vec<u8>, u8),
    Osc(Vec<Vec<u8>>, bool),
}

#[derive(Default)]
struct Trace {
    events: Vec<Event>,
    /// `print_unicode_bulk` runs that held ASCII: the joined runs the reference never makes.
    joined_runs: usize,
}

impl ActionSink for Trace {
    fn print(&mut self, c: char) {
        self.events.push(Event::Print(c));
    }
    fn print_unicode_bulk(&mut self, chars: &Provenance<[char], Pty>) {
        if chars.as_ref().iter().any(char::is_ascii) {
            self.joined_runs += 1;
        }
        for &c in chars.as_ref() {
            self.print(c);
        }
    }
    fn execute(&mut self, byte: u8) {
        self.events.push(Event::Execute(byte));
    }
    fn csi_dispatch(
        &mut self,
        params: &Provenance<[u16], Pty>,
        intermediates: &Provenance<[u8], Pty>,
        final_byte: u8,
    ) {
        self.csi_dispatch_with_subparams(params, intermediates, final_byte, 0);
    }
    fn csi_dispatch_with_subparams(
        &mut self,
        params: &Provenance<[u16], Pty>,
        intermediates: &Provenance<[u8], Pty>,
        final_byte: u8,
        subparam_mask: u32,
    ) {
        self.events.push(Event::Csi(
            params.as_ref().to_vec(),
            intermediates.as_ref().to_vec(),
            final_byte,
            subparam_mask,
        ));
    }
    fn esc_dispatch(&mut self, intermediates: &Provenance<[u8], Pty>, final_byte: u8) {
        self.events
            .push(Event::Esc(intermediates.as_ref().to_vec(), final_byte));
    }
    fn osc_dispatch_with_terminator(
        &mut self,
        params: &Provenance<[&[u8]], Pty>,
        bel_terminated: bool,
    ) {
        self.events.push(Event::Osc(
            params.as_ref().iter().map(|p| p.to_vec()).collect(),
            bel_terminated,
        ));
    }
}

/// What a read boundary leaves of the parser: its state and the UTF-8 sequence it holds.
fn view(p: &Parser) -> (State, Vec<u8>) {
    (
        p.state,
        p.utf8_buffer
            .get(..usize::from(p.utf8_len))
            .unwrap_or(&[])
            .to_vec(),
    )
}

/// A seeded xorshift stream.
struct Rng(u64);

impl Rng {
    fn below(&mut self, n: usize) -> usize {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        (self.0 % n.max(1) as u64) as usize
    }
}

const TEXT: &[&str] = &[
    "hello",
    "a",
    " ",
    "  ",
    ", ",
    "0123456789",
    "\u{411}\u{44b}\u{441}\u{442}\u{440}\u{430}\u{44f}",
    "\u{3bb}\u{3cc}\u{3b3}\u{3bf}\u{3c2}",
    "\u{6f22}\u{5b57}",
    "\u{d55c}\u{ad6d}",
    "\u{3042}\u{3044}",
    "\u{1f600}",
    "\u{1f468}\u{200d}\u{1f469}",
    "e\u{301}",
    "\u{80}\u{7ff}\u{800}\u{d7ff}\u{e000}\u{ffff}\u{10000}\u{10ffff}",
    "\u{85}\u{a0}\u{ff}",
];

const BYTES: &[&[u8]] = &[
    b"\r",
    b"\n",
    b"\t",
    b"\x7f",
    b"\x1b[1;31m",
    b"\x1b[38:2:1:2:3m",
    b"\x1b[0m",
    b"\x1b(0",
    b"\x1b]0;title\x07",
    b"\x1b]8;;http://x/\x1b\\",
    &[0x80],
    &[0xbf],
    &[0x9b],
    &[0xc0, 0x80],
    &[0xc1, 0xbf],
    &[0xe0, 0x80, 0x80],
    &[0xed, 0xa0, 0x80],
    &[0xf0, 0x80, 0x80, 0x80],
    &[0xf4, 0x90, 0x80, 0x80],
    &[0xf5],
    &[0xfe],
    &[0xff],
    &[0xe4, 0xb8],
    &[0xf0, 0x9f, 0x98],
    &[0xd0],
];

fn stream(rng: &mut Rng) -> Vec<u8> {
    let mut out = Vec::new();
    for _ in 0..2 + rng.below(24) {
        match rng.below(10) {
            0..=5 => out.extend_from_slice(TEXT[rng.below(TEXT.len())].as_bytes()),
            6..=8 => out.extend_from_slice(BYTES[rng.below(BYTES.len())]),
            _ => {
                // Past the run buffer: a long line of words, ASCII gaps between leads that the run
                // joins, or gaps longer than it joins.
                let word = match rng.below(3) {
                    0 => "\u{43a}\u{43e}\u{440}\u{438}\u{447}\u{43d}\u{435}\u{432}\u{430}\u{44f} ",
                    1 => "\u{4e2d}abcdefghijklmnopqrst",
                    _ => "\u{4e2d}abcdefghijklmnopqrstuvwxyz0123456789",
                };
                for _ in 0..rng.below(40) {
                    out.extend_from_slice(word.as_bytes());
                }
            }
        }
    }
    out
}

/// Read boundaries for `bytes`: random cuts, and cuts inside multi-byte sequences.
fn cuts(rng: &mut Rng, bytes: &[u8]) -> Vec<usize> {
    let mut cuts: Vec<usize> = (0..rng.below(6))
        .map(|_| rng.below(bytes.len() + 1))
        .collect();
    let inside: Vec<usize> = (1..bytes.len())
        .filter(|&i| (bytes[i] & 0xc0) == 0x80)
        .collect();
    for _ in 0..rng.below(6) {
        if !inside.is_empty() {
            cuts.push(inside[rng.below(inside.len())]);
        }
    }
    cuts.sort_unstable();
    cuts.dedup();
    cuts
}

fn chunks<'a>(bytes: &'a [u8], cuts: &[usize]) -> Vec<&'a [u8]> {
    let mut out = Vec::new();
    let mut from = 0;
    for &cut in cuts.iter().chain(std::iter::once(&bytes.len())) {
        out.push(&bytes[from..cut]);
        from = cut;
    }
    out
}

/// Feed `reads` to a parser on the fast or the reference path; the trace and the view after
/// each read.
fn run(reads: &[&[u8]], reference: bool) -> (Trace, Vec<(State, Vec<u8>)>) {
    let mut parser = Parser::new();
    parser.set_reference_runs(reference);
    let mut trace = Trace::default();
    let mut views = Vec::new();
    for read in reads {
        parser.advance_fast(read, &mut trace);
        views.push(view(&parser));
    }
    (trace, views)
}

/// How a decoder under test reads a stream cut into reads.
type Decoder = fn(&[&[u8]]) -> (Trace, Vec<(State, Vec<u8>)>);

fn fast(reads: &[&[u8]]) -> (Trace, Vec<(State, Vec<u8>)>) {
    run(reads, false)
}

/// The planted decode bug at a split boundary, for the negative control: the fast decoder that
/// loses a well-formed multi-byte sequence a read boundary cuts (its carry is never kept).
fn planted_split_bug(reads: &[&[u8]]) -> (Trace, Vec<(State, Vec<u8>)>) {
    let mut parser = Parser::new();
    let mut trace = Trace::default();
    let mut views = Vec::new();
    for read in reads {
        parser.advance_fast(read, &mut trace);
        parser.utf8_len = 0;
        parser.utf8_expected = 0;
        views.push(view(&parser));
    }
    (trace, views)
}

/// How a decoder's reads of one generated stream compare to the reference decoder's and the
/// per-byte decoder's: `None` when they agree, else whether the sink calls differ (not only the
/// state a read leaves) and the case.
fn compare(decoder: Decoder, seed: u64) -> (usize, Option<(bool, String)>) {
    let mut rng = Rng(0xD1B5_4A32_D192_ED03 ^ seed.wrapping_mul(0x9E37_79B9_7F4A_7C15));
    let bytes = stream(&mut rng);
    let cuts = cuts(&mut rng, &bytes);
    let reads = chunks(&bytes, &cuts);
    let (got, got_views) = decoder(&reads);
    let (reference, reference_views) = run(&reads, true);
    assert_eq!(reference.joined_runs, 0, "the reference path joined a run");
    let bytewise: Vec<&[u8]> = bytes.chunks(1).collect();
    let (per_byte, _) = run(&bytewise, false);
    let events_differ = got.events != reference.events || got.events != per_byte.events;
    if events_differ || got_views != reference_views {
        let case = format!(
            "seed {seed}: {bytes:02x?} cut at {cuts:?}\ngot {:?}\nreference {:?}\nper byte {:?}\n\
             views {got_views:?} vs {reference_views:?}",
            got.events, reference.events, per_byte.events
        );
        return (got.joined_runs, Some((events_differ, case)));
    }
    (got.joined_runs, None)
}

const CASES: u64 = 4000;

#[test]
fn joined_runs_print_what_the_reference_and_per_byte_decoders_print() {
    let mut joined = 0;
    for seed in 1..=CASES {
        let (runs, divergence) = compare(fast, seed);
        if let Some((_, case)) = divergence {
            panic!("the joined multi-byte runs diverge: {case}");
        }
        joined += runs;
    }
    assert!(
        joined > 4000,
        "only {joined} runs joined ASCII: the streams hardly reach the joined path"
    );
}

#[test]
fn the_differential_catches_a_planted_split_boundary_bug() {
    let caught = (1..=CASES)
        .filter(|&seed| matches!(compare(planted_split_bug, seed).1, Some((true, _))))
        .count();
    assert!(
        caught > 0,
        "a decoder that loses a sequence cut by a read boundary printed what the reference \
         prints on every stream"
    );
}

#[test]
fn a_joined_run_is_one_bulk_print_up_to_the_run_capacity() {
    let line = "\u{411}\u{44b}\u{441}\u{442}\u{440}\u{430}\u{44f} \u{43b}\u{438}\u{441}\u{430} \u{43f}\u{440}\u{44b}\u{433}\u{430}\u{435}\u{442}";
    let (trace, _) = run(&[line.as_bytes()], false);
    assert_eq!(trace.joined_runs, 1, "one run for the line");
    assert_eq!(
        trace.events,
        line.chars().map(Event::Print).collect::<Vec<_>>()
    );
    // ASCII that no lead follows stays for the printable scan.
    let (trace, _) = run(&["\u{4e2d} 0123\r\n".as_bytes()], false);
    assert_eq!(trace.joined_runs, 0);
}
